 @Test void listUsesReadOnlyPostAndDoesNotInventTotal(){var page=catalog.list(1L,new ElevenstProducts.Query(null,"지갑",null,null,null,null,0,20));assertThat(page.items()).hasSize(1);assertThat(page.hasNext()).isFalse();assertThat(requests).containsExactly("POST /rest/prodmarketservice/prodmarket");}
