 @Test void createSends128000Minus41000AndLinksReturnedIdsWithoutSecondPost(){var p=writer.prepare(1L,document(),null,false);var xml=p.steps().getFirst().bodyJson();assertThat(xml).contains("<selPrc>128000</selPrc>","<dscAmtPercnt>41000</dscAmtPercnt>","<colOptPrice>0</colOptPrice>").doesNotContain("prdImage05");var result=writer.execute(1L,p,p.steps().getFirst(),null);assertThat(result.state()).isEqualTo(State.CONFIRMED);assertThat(result.mapping().options().getFirst().optionId()).isEqualTo(option);assertThat(writer.execute(1L,p,p.steps().getFirst(),result.mapping()).code()).isEqualTo("ALREADY_REGISTERED");assertThat(requests.stream().filter(r->r.equals("POST /rest/prodservices/product"))).hasSize(1);}
 @Test void lostCreateCannotBeReconciledBySellerCode(){var p=writer.prepare(1L,document(),null,false);lost=true;var result=writer.execute(1L,p,p.steps().getFirst(),null);assertThat(result.state()).isEqualTo(State.UNKNOWN);assertThat(writer.reconcile(1L,p,p.steps().getFirst(),result).code()).isEqualTo("CREATE_UNCONFIRMED");assertThat(requests.stream().filter(r->r.equals("POST /rest/prodservices/product"))).hasSize(1);}
 @Test void priceAndStockEditsSendOnlySelectedStepsAndPreserveWeight(){var o=docs.standalone(1L,"101");var current=docs.input(o.document());var rows=current.options().stream().map(r->new PartnerEditor.Option(r.id(),r.name(),r.sku(),r.price(),"0",r.attributes(),r.usable())).toList();var changes=List.of(new MarketplaceEditing.Change("partner.fields.selPrc",null,"130000"),new MarketplaceEditing.Change("partner.options",null,rows));var p=writer.prepareSelected(1L,o.document(),o.mapping(),false,o.document(),changes);assertThat(p.steps()).extracting(Step::type).containsExactly(Type.PRICE,Type.STOCK);var price=writer.execute(1L,p,p.steps().getFirst(),o.mapping());assertThat(price.state()).isEqualTo(State.CONFIRMED);var stock=writer.execute(1L,p,p.steps().getLast(),o.mapping());assertThat(stock.state()).isEqualTo(State.CONFIRMED);assertThat(requests).noneMatch(r->r.startsWith("PUT /rest/prodservices/product/"));}
 @Test void unobservedFullFieldsBlockWholePutButPriceIsAllowed(){var o=docs.standalone(1L,"101");assertThatThrownBy(()->writer.prepareSelected(1L,o.document(),o.mapping(),false,o.document(),List.of(new MarketplaceEditing.Change("partner.fields.prdNm",null,"새 이름")))).isInstanceOf(cc.ataglace.molebutter.common.api.InputValidationFailure.class).hasMessageContaining("미확인");assertThat(requests).noneMatch(r->r.startsWith("PUT "));}
 @Test void savedNativeInputRoundTripsWithoutDiscardingOtherMarkets(){var d=MarketplaceDocuments.normalize(json.readValue(json.writeValueAsString(document()),Document.class));assertThat(d.markets().get(Market.ELEVENST).elevenst().editorInput().fields()).containsEntry("selPrc","128000");}
 @Test void schemaFixtureAndNativeInheritanceStayDurable()throws Exception{
  java.nio.file.Files.createDirectories(java.nio.file.Path.of("../molebutter-app/target/ui-fixtures"));java.nio.file.Files.writeString(java.nio.file.Path.of("../molebutter-app/target/ui-fixtures/elevenst-schema.json"),json.writeValueAsString(ElevenstRules.SCHEMA));
  var d=document();var m=d.markets().get(Market.ELEVENST);d=ElevenstInheritance.state(d,ElevenstInheritance.EMPTY);var old=docs.input(d);var f=new LinkedHashMap<String,Object>(old.fields());f.put("prdNm","");var row=old.options().getFirst();var changed=new PartnerEditor.Input(f,List.of(new PartnerEditor.Option(row.id(),row.name(),row.sku(),row.price(),"0",row.attributes(),row.usable())),old.images(),old.description(),old.noticeType(),old.notices(),old.certifications());
  d=ElevenstInheritance.mark(d,PartnerFormSupport.withInput(d,"ELEVENST",changed),json);d=json.readValue(json.writeValueAsString(d),Document.class);
  var common=d.common();d=new Document(d.id(),d.revision(),new Common(common.productCode(),"공통 새 이름",common.productName(),common.brand(),common.manufacturer(),common.origin(),common.material(),common.model(),common.afterService(),common.taxType(),common.adultOnly()),d.options(),d.stockMode(),d.productQuantity(),d.services(),d.media(),d.delivery(),d.selectedMarkets(),d.markets());
  var next=docs.input(docs.newDocument(d));assertThat(next.fields().get("prdNm")).isEqualTo("");assertThat(next.options().getFirst().quantity()).isEqualTo("0");
 }
